    "open_answer": "",
    "explanation": "Dolaşımdaki **monositler** dokulara göç ettiklerinde **makrofajlara** farklılaşırlar. Profesyonel antijen sunan hücreler (APC) olarak fagositoz yaptıkları antijenleri işleyip yüzeylerindeki **MHC sınıf II** molekülleri aracılığıyla CD4+ T yardımcı lenfositlere sunarlar.",
