    "q_num": 59,
    "subject": "Fizyoloji",
    "professor": "Belirtilmemiş",
    "question": "Aşağıdakilerden hangisi kan basıncının uzun dönem regülasyonunda önemli rol oynar?",
    "options": [
      {
        "letter": "A",
        "text": "renin-anjiotensin sistemi"
      },
      {
        "letter": "B",
        "text": "vasküler stres relaksasyonu"
      },
      {
        "letter": "C",
        "text": "basınç diürezi ve basınç natriürezi"
      },
      {
        "letter": "D",
        "text": "kemoreseptör refleks"
      },
      {
        "letter": "E",
        "text": "merkezi sinir sisteminin iskemik yanıtı"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Sinirsel refleksler ve hormonal mekanizmalar kısa ve orta vadeli tansiyon kontrolü sağlarken, arter basıncının uzun dönem kalıcı regülasyonunda en baskın mekanizma böbreklerin sergilediği **basınç diürezi ve basınç natriürezi** (renal-sıvı hacim kontrol mekanizması) sistemidir.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
