    "explanation": "Kalp duvarı dışta visseral perikard (epikart), ortada kas yapılı miyokart ve içte endotelli endokart tabakalarından oluşur; tabakaların histolojik ve fizyolojik niteliklerine ilişkin **III ve IV numaralı ifadeler yanlıştır**.",
