    "open_answer": "",
    "explanation": "Embriyonik kardiyovasküler gelişimde sinus venosus'un sol boynuzu (sol kornusu) involüsyona uğrayarak kalbin venöz drenajını toplayan **sinus coronarius**'u ve v. obliqua atrii sinistri'yi oluşturur. Sağ boynuz ise sağ atriyumun arka düz duvarına (sinus venarum) katılır.",
