    "open_answer": "",
    "explanation": "**Fallot tetralojisinin** dört ana anatomik anomalisi: Pulmoner infundibuler stenoz, geniş ventriküler septal defekt (VSD), dekstropoze (ata binen) aorta ve sağ ventrikül konsantrik hipertrofisidir. **Atriyal septal defekt (ASD)** tetralojide bulunmaz; ASD eşlik ederse bu tablo Fallot pentalojisi olarak adlandırılır.",
