    "q_num": 70,
    "subject": "Fizyoloji",
    "professor": "Sinan Yürüker",
    "question": "İkinci trimesterde  embriyoda en fazla kan üretimi nerede olur?",
    "options": [
      {
        "letter": "A",
        "text": "vitellus kesesi"
      },
      {
        "letter": "B",
        "text": "karaciğer"
      },
      {
        "letter": "C",
        "text": "dalak"
      },
      {
        "letter": "D",
        "text": "kemik iliği"
      },
      {
        "letter": "E",
        "text": "timus"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "İntrauterin hematopoez evrelerinde ikinci trimester boyunca ana kan hücresi üretim merkezi **karaciğerdir** (hepatik dönem; dalağın da kısmi katkısı vardır). Üçüncü trimesterden itibaren ve doğum sonrasında ise hematopoez kalıcı olarak kemik iliğine geçer.",
