    "question": "Aşağıda verilen ifadelerden hangisi doğru değildir?",
    "options": [
      {
        "letter": "A",
        "text": "Bütün çizgili kaslarda kasılma etkinliği, kas lifi zarında oluşan aksiyon potansiyeli ile başlatılır."
      },
      {
        "letter": "B",
        "text": "Kalp kasında yeni bir kasılma için mutlak refraktör dönemi izleyen yeni bir aksiyon potansiyeli gerekir."
      },
      {
        "letter": "C",
        "text": "Kalp kası pacemakar hücrelerinin kendiliğinden ve otomatik olarak ortaya çıkma özellikleri vardır."
      },
      {
        "letter": "D",
        "text": "Kalp kasında üst üste binme sonucunda görülen kasılmalar tetanik kasılmalar olarak adlandırlır."
      },
      {
        "letter": "E",
        "text": "Kalp kasındaki iletinin doğrudan ve hızla bir hücreden diğerine yayılma özelliği vardır."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Kalp kasında aksiyon potansiyelinin refrakter periyodu mekanik kasılma süresi kadar uzundur (yaklaşık 250 ms). Bu uzun refrakter periyot kasılmaların üst üste binmesini (sumasyon) ve kalbin **tetanik kasılmaya girmesini kesinlikle engeller**; kalbin ritmik pompa fonksiyonunun devamı için tetani oluşmaz.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
