    "professor": "Belirtilmemiş",
    "question": "Standart bir EKG çıktısının değerlendirilmesi ile ilgili;\nI. P dalgası atriyum depolarizasyonunu gösterir.\nII. QRS kompleksi ventrikül depolarizasyonunu gösterir.\nIII. PR aralığı ventrikül repolarizasyon süresini gösterir.\nIV. T dalgası ventrikül repolarizasyonunu gösterir.\nV. Kalp hızı R-R aralıklarından hesaplanabilir.\nifadelerinden hangileri doğrudur?",
