    "q_num": 1,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Aşağıdakilerden hangisi mediastinum posteriorda bulunmaz?",
    "options": [
      {
        "letter": "A",
        "text": "Ductus thoracicus"
      },
      {
        "letter": "B",
        "text": "V.azygos"
      },
      {
        "letter": "C",
        "text": "V.cava superior"
      },
      {
        "letter": "D",
        "text": "N.vagus"
      },
      {
        "letter": "E",
        "text": "Aorta thoracica"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "**Vena cava superior**, mediastinum superius ve mediastinum medium'da seyreder; mediastinum posterius'ta bulunmaz. Aorta thoracica, ductus thoracicus, oesophagus, v. azygos ve n. vagus ise arka mediastenin temel yapılarıdır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
