    "year": "2019-2020 (Solunum)",
    "q_num": 3,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Akciğerde ilk gaz alışverişi hangi yapıda başlar?",
    "options": [
      {
        "letter": "A",
        "text": "Bronchus principalis"
      },
      {
        "letter": "B",
        "text": "Bronchiolus lobularis"
      },
      {
        "letter": "C",
        "text": "Bronchiolus respiratorius"
      },
      {
        "letter": "D",
        "text": "Saccus alveolaris"
      },
      {
        "letter": "E",
        "text": "Alveol"
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "İletici hava yollarının sonlandığı terminal bronşiyolden hemen sonra gelen **respiratuvar bronşiyol (bronchiolus respiratorius)**, duvarında tek tük alveol keseleri belirdiği için gaz alışverişinin başladığı ilk solunum bölümüdür.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
