    "explanation": "**Lingula pulmonis**, sol akciğer üst lobunun (lobus superior) alt-ön kenarında incisura cardiaca'nın hemen altında yer alan dil şeklindeki anatomik uzantıdır ve sağ akciğerin orta lobunun embriyolojik dengidir.",
