    "professor": "Belirtilmemiş",
    "question": "Traketomi işleminde trakeaya giriş nerden yapılır?",
    "options": [
      {
        "letter": "A",
        "text": "1 ve2. Trakea halkaları arasından"
      },
      {
        "letter": "B",
        "text": "2 ve 3. Trakea halkaları arasından"
      },
      {
        "letter": "C",
        "text": "Cartilago cricoidea ile 1. Trakea halkaları arasından"
      },
      {
        "letter": "D",
        "text": "Bifurcatio tracheadan"
      },
      {
        "letter": "E",
        "text": "Cartilaga thyroidea ile Cartilago cricoidea arasından"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Cerrahi trakeotomi işleminde kıkırdak halkalara ve tiroid bezine zarar vermeden güvenli hava yolu sağlamak amacıyla trakeotomi kanülü sıklıkla **2. ve 3. trakea halkaları arasından** açılan açıklıktan yerleştirilir.",
    "note": "",
