    "professor": "Belirtilmemiş",
    "question": "Aşağıdaki yapılardan hangisi membrana thyrohyoideyı deler?",
    "options": [
      {
        "letter": "A",
        "text": "N.laryngealis superiorun ramus internusu"
      },
      {
        "letter": "B",
        "text": "N.laryngealis superiorun ramus externusu"
      },
      {
        "letter": "C",
        "text": "N.laryngealis inferior"
      },
      {
        "letter": "D",
        "text": "A. laryngealis inferior"
      },
      {
        "letter": "E",
        "text": "A.thyroidea superior"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "**N. laryngeus superior'un ramus internus'u**, a. laryngea superior ile birlikte **membrana thyrohyoidea**'yı delerek larinkse girer ve vokal kordların üstünde kalan larinks mukozasının duyusunu taşır.",
    "note": "",
