    "explanation": "Burun boşluğunun üst duvarını (tavanını) os frontale, os nasale, os ethmoidale (lamina cribrosa) ve os sphenoidale yapar. **Os palatinum** (lamina horizontalis) ise burun boşluğunun alt duvarını (sert damak / taban) oluşturur.",
