    "question": "Aşağıdakilerden hangisi asit baz bozukluklarında böbreklerin görevlerinden değildir?",
    "options": [
      {
        "letter": "A",
        "text": "Proksimal tübüllerden bikarbonat reabsorbsiyonunu ayarlamak"
      },
      {
        "letter": "B",
        "text": "İdrarı asitleştirmek veya alkalileştirmek"
      },
      {
        "letter": "C",
        "text": "Amonyum üretimi veya atılımının arttırılması"
      },
      {
        "letter": "D",
        "text": "Santral kemoreseptörlerin uyarılımı"
      },
      {
        "letter": "E",
        "text": "Yeni bikarbonat oluşturmak"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Böbrekler asit-baz regülasyonunu bikarbonat geri emilimi, yeni HCO₃⁻ sentezi ve idrarla H⁺ / amonyum (NH₄⁺) atılımıyla yönetir. **Santral kemoreseptörlerin uyarılması** ise solunum sisteminin medüller merkezlerine ait bir fonksiyondur, böbreğin görevi değildir.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
