    "question": "Bir hastanın arteriyel kan gazı analizinde elde edilen sonuçlar aşağıdaki şekildedir:  Ph:7.20 PCO2:75 mmHg HCO3:24mEq/L BE:+2 mmol/L (N) Buna göre olası tanıaşağıdakilerden hangisi olabilir?",
