    "explanation": "Kemoreseptörler hipoksi (düşük PaO₂), hiperkapni (yüksek PaCO₂) ve asidoz (yüksek H⁺) ile güçlü biçimde uyarılır. **Hiperventilasyon** ise kandan CO₂'yi uzaklaştırıp hipokapni ve alkaloza yol açarak kemoreseptör aktivitesini baskılar (stimülasyona neden olmaz).",
