    "explanation": "Solunumun primer ritmik jeneratörü olan medüller merkezlerin (DRG ve VRG) diyaframı innerve eden motor nöronlarla (C3-C5) bağlantısı koparsa solunum durur. Bu nedenle **beyin sapının medullanın kaudal ucu hizasından kesilmesi** spontan solunumu tamamen sonlandırır.",
    "note": "",
