    "explanation": "Medulla oblongata'da yer alan esas inspiratuar nöronlar (Dorsal Solunum Grubu), sakin solunum sırasında frenik sinir aracılığıyla **inspirasyon kaslarına (diyafram) düzenli olarak patlamalar (rampa sinyalleri) halinde uyarılar yollar**; sakin ekspirasyon ise pasif olarak gerçekleşir.",
