    "open_answer": "",
    "explanation": "Solunum yollarında terminal bronşiyolden sonra gelen respiratuvar bronşiyoller ve **alveolar duktuslar (ductus alveolaris)** duvarlarında alveol barındırdıkları için gaz alışverişine aktif olarak katılan solunum bölgesi yapılarıdır. Bronşlar ve terminal bronşiyoller sadece iletici yoldur.",
