    "explanation": "Nazal konkanın respiratuvar epitelinde silli silindirik hücreler, goblet hücreleri, fırçamsı (brush) hücreler, bazal hücreler ve küçük granüllü nöroendokrin hücreler bulunur. **Destek (sustentaküler) hücreleri** ise respiratuvar bölgede değil, regio olfactoria (koku) epitelinde yer alır.",
