    "explanation": "Akciğer parankimini sıkıca saran **visseral plevra**, intraembriyonik lateral mezodermin iç tabakası olan **splanknik (splanknopleurik) mezodermden** gelişir. Parietal plevra ise somatik mezoderm kökenlidir.",
