    "explanation": "Birinci kosta seviyesi toraks girişinde (T1-T2) yer alır. Trakeanın bifurkasyonu ve **bronchus principalis dexter**'in başlangıcı ise T4-T5 (angulus sterni) seviyesindedir; bu nedenle 1. kosta düzeyindeki horizontal kesitte sağ ana bronş henüz görülmez.",
