    "explanation": "EKG trasesinde normal morfolojide P dalgaları ve ardından gelen QRS kompleksleri düzenli aralıklarla izlenmekte, ancak atım hızı dakikada 100 vuru sınırının üzerinde seyretmektedir; bu ritim **sinüs taşikardisi**dir.",
