    "subject": "Fizyoloji",
    "professor": "Barış Uzunok",
    "question": "Bir kapiller yatakta kapiller basınç 20 mmHg, plazma kolloid ozmotik basıç 30 mmHg iken interstisyel sıvı basıncı 5 mmHg ve interstisyel sıvı kolloid ozmotik basıncı 17 mmHg ise Net Filtrasyon basıncı ne kadardır?",
    "options": [
      {
        "letter": "A",
        "text": "+2 mmHg"
      },
      {
        "letter": "B",
        "text": "-2 mmHg"
      },
      {
        "letter": "C",
        "text": "+22 mmHg"
      },
      {
        "letter": "D",
        "text": "-22 mmHg"
      },
      {
        "letter": "E",
        "text": "+28 mmHg"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Starling net filtrasyon basıncı formülü: NFB = (Pc - Pi) - (πc - πi) = (20 - 5) - (30 - 17) = 15 - 13 = **+2 mmHg**'dir. Pozitif değer sıvının damardan interstisyuma doğru net filtrasyonunu gösterir.",
