    "open_answer": "",
    "explanation": "Ventrikül aksiyon potansiyelinde depolarizasyonun (Faz 0) hemen ardından voltaj kapılı Na⁺ kanallarının inaktive olması ve geçici dışa akımlı K⁺ (I_to) kanallarının açılmasıyla oluşan erken hızlı repolarizasyon evresi **Faz 1**dir.",
