    "q_num": 73,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Belirtilmemiş",
    "question": "Nazal konka olfaktör bölüm için aşağıdakilerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Yalancı çok katlı silli silindirik epitel ile döşelidir"
      },
      {
        "letter": "B",
        "text": "Epitelde goblet hücreleri izlenir"
      },
      {
        "letter": "C",
        "text": "Olfaktör hücreler bipolar nörondur"
      },
      {
        "letter": "D",
        "text": "Lamina propriya Bowman bezleri içerir"
      },
      {
        "letter": "E",
        "text": "Bağ doku içerisinde olfaktör sinirler bulunur"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Regio olfactoria koku epitelinde olfaktör bipolar nöronlar, destek (sustentaküler) hücreleri ve bazal hücreler bulunur; **goblet (kadeh) hücreleri izlenmez**. Koku epitelini nemlendiren seröz salgı lamina propriadaki Bowman bezlerince üretilir.",
    "note": "",
    "q_type": "mcq",
