    "professor": "Belirtilmemiş",
    "question": "Bir çocukta yer fıstığı yedikten sonra tüm vücutta kaşıntı ve döküntü semptomları gösteren yer fıstığı alerji hikayesi mevcuttur. Çocuğun semptomları yanlışlıkla tekrarlayan karşılaşmalardan dolayı daha da ciddi hale gelmiştir. Bu çocuk için yer fıstığı büyük oranda nasıl tanımlanır?",
