    "question": "Belli bir antijene karşı daha sonar alerji geliştiren bir hastada antijene karşı ilk yanıt IgM sınıfından immünoglobülinlerle gerçekleşmektedir. Buna karşın zamanla antijene özgül IgE baskın hale gelmektedir. IgM’den IgE yanıtına doğru olan bu değişime aşağıdakilerden hangisi sebep olmaktadır?",
