    "professor": "Barış Uzunok",
    "question": "İnspirasyon sırasında meydana gelen olaylar hangisinde doğru sıralamayla verilmiştir?l. Akciğer hacmi genişlerll. Atmosfer basıncı akciğerlere dolmaya başlarlll. İnternal kostal kaslar kasılırlV. Diyafram kası gevşerV. Basınç artarVI. Frenik sinir uyarılması",
