    "subject": "Fizyoloji",
    "professor": "Arzu Şahin",
    "question": "Öğrencinin işaretlediği 25 — :SantraI sinir sisteminin iskemik cevabı sempatik sistemi güçlü olarak uyarır, ancak bu refleksin devreye girmesi için kan basıncının belli bir kritik değerin altına inmesi gerekir. Bu değer aşağıdakilerden hangisidir?",
