    "explanation": "Kardiyak aksiyon potansiyelinin Faz 2 plato döneminde tüm ventrikül miyokardı depolarize kalır ve net bir potansiyel farkı oluşmaz; yüzeyel EKG'de bu faz izoelektrik hat üzerindeki **ST segmentine** karşılık gelir.",
