    "q_num": 57,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Sinan Yürüker",
    "question": "Karotid sinus için aşağıdakilerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Baroreseptördür"
      },
      {
        "letter": "B",
        "text": "Kemoreseptördür"
      },
      {
        "letter": "C",
        "text": "Kan basıncındaki değişiklikleri saptar"
      },
      {
        "letter": "D",
        "text": "Adventisyasında sinir sonlanmaları bulunur"
      },
      {
        "letter": "E",
        "text": "İntimasında sinir sonlanmaları bulunur-"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "A. carotis interna'nın bifurkasyon kökünde yer alan **sinus caroticus**, arteriyel kan basıncındaki gerilmeyi algılayan bir **baroreseptördür**. Kandaki parsiyel gaz basınçlarını ve pH'yı algılayan kemoreseptör yapı ise glomus caroticum'dur.",
