    "subject": "Histoloji ve Embriyoloji",
    "professor": "Sinan Yürüker",
    "question": "hafta ortası - 5_ hana sonu AV kanalın dmsal ve ventral duvarında endokardiyal yastıklar Oluşur. mezen hücrelerin en dokardiyal yastıklar büyür, birbirlerine yaklaşır ve Sağ ve sd AV kanallar oluşur. 65— 'Nazal kavitenin solunum bölümü için aşağıdakilerden hangisi yanlıştır?",
