    "question": "Doğumla birlikte (veya doğumdan kısa süre sonra) aşağıdaki fetal dolaşım şantlarından hangileri kapanır?\nI. Foramen ovale\nII. Duktus venozus\nIII. Duktus arteriozus\nIV. Foramen primum\nV. İnterventriküler septum",
