    "question": "yanlıştır? I. Kalp kasında aksiyon potansiyelleri daha uzun sürelidir.ll. Kalp kasında T tübülleri İskelet kasındakinden daha geniştir. III. Kalp kasında Sarkoplazmik retikulum iskelet kasından daha gelişmiştir.IV. Kalp kasında aksiyon potansiyeli kasılmayı tetikleyici iken iskelet kasında tetikleyici ve kontrol edici rolü vardır. V. Kalp kasın iskelet kasından daha zengin mitokondri taşır.",
