    "question": "ipopolisakkarid -- --- ,dsRNA cpG DNA ssRNA -----gibi patern tanıma reseptörleri (PRR) ile tanınırlar. Boşluklara gelecek patern tanıma reseptör tipleri aşağıdakilerden hangisinde doğru bir şekilde verilmiştir?",
