    "q_num": 91,
    "subject": "Histoloji ve Embriyoloji",
    "professor": "Hasan Asker",
    "question": "Histolojik kesitte duvarında hiyalin kıkırdak plakları, düz kas tabakası (Reisseisen kası) ve yalancı çok katlı silyalı prizmatik epitel (solunum epiteli) içeren akciğer içi hava yolu aşağıdakilerden hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "Terminal bronşiyol"
      },
      {
        "letter": "B",
        "text": "İntrapulmoner bronş"
      },
      {
        "letter": "C",
        "text": "Respiratuvar bronşiyol"
      },
      {
        "letter": "D",
        "text": "Alveolar kanal"
      },
      {
        "letter": "E",
        "text": "Alveolar kese"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Duvarında düzensiz hiyalin kıkırdak plakları, kesintisiz Reisseisen düz kas tabakası, serömüköz bezler ve yalancı çok katlı silli epitel barındıran akciğer hava yolu **intrapulmoner bronş**tur. Bronşiyollerde kıkırdak plakları ve bezler tamamen kaybolur.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
