    "subject": "Histoloji ve Embriyoloji",
    "professor": "Hasan Asker",
    "question": "Kalp duvarı histolojisinde endokardın hemen altında yer alan ve Purkinje liflerini (impuls iletim liflerini) barındıran gevşek bağ dokusu katmanı aşağıdakilerden hangisidir?",
