    "open_answer": "",
    "explanation": "Mastektomi ve aksiller lenf nodu diseksiyonu geçirmiş kadın hastalarda lenfatik drenaj bozulduğundan, manşon basıncının oluşturacağı vasküler hasar ve lenfödem atağını önlemek için **mastektomi yapılmış taraftaki koldan kan basıncı ölçümü yapılmaz**.",
