    "professor": "Soycan Mızrak",
    "question": "Kusma ve halsizlik şikayetleri ile hastaneye başvuran hastanın öyküsünde 15 gün önce mide ülseri tanısı ile tedavi altına girdiği bilgisi alınmıştır. tanı alındıktan sonra süt diyetine girmiş ve kalsiyum karbonat tedavisi uygulanmış. Yapılan muayeneden sonra tetkikleri istenen hastadan aşağıdaki kan gazları sonuçları elde edilmiştir. Buna göre hangi tanıma en yakındır? pH: 7,50PaC02: 50",
