    "open_answer": "",
    "explanation": "Sol ventrikül ön duvarını (anterior miyokardı) doğrudan gören göğüs derivasyonları **V3 ve V4**'tür. Bu derivasyonlardaki ST elevasyonu ve patolojik Q dalgaları anterior MI tanısında öncelikli olarak kullanılır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
