    "explanation": "Fizyolojik şant, perfüzyonun ventilasyona oranla fazla olduğu (düşük V/Q) durumlarda oluşur. Ayakta duran bir bireyde yer çekimi kan akımını akciğerin alt kısımlarına yığar; bu nedenle **akciğer tabanında** perfüzyon ventilasyondan belirgin şekilde fazladır ve fizyolojik şant eğilimi izlenir.",
