    "subject": "Fizyoloji",
    "professor": "Belirtilmemiş",
    "question": "ACh salgılayan parasempatik sinir sistemi, hangi reseptör ve ikincil haberci sistemini kullanarak kalp üzerinde fizyolojik etkisini gösterir?",
    "options": [
      {
        "letter": "A",
        "text": "BARBOR"
      },
      {
        "letter": "B",
        "text": "M2 reseptörü- G proteini,"
      },
      {
        "letter": "C",
        "text": "M2 reseptörü- IP3,"
      },
      {
        "letter": "D",
        "text": "M2 reseptörü- Nitrikoksit,"
      },
      {
        "letter": "E",
        "text": "M3 reseptörü- cAMP"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Parasempatik sinir sisteminden salınan asetilkolin, kalp miyositlerindeki **M2 muskarinik reseptörlerine** bağlanır; **Gi proteini** aracılığıyla adenilat siklazı inhibe edip cAMP'yi azaltır ve GIRK potasyum kanallarını açarak negatif kronotrop ve dromotrop etki yapar.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
