    "q_num": 2,
    "subject": "Temel Tıp Bilimleri",
    "professor": "Serdar Güngör",
    "question": "L-selektin adezyon molekülü yukarıdaki hücrelerin hangilerinde bulunur? I. Endotel                           II. Nötrofi                      III.T hücresi",
    "options": [
      {
        "letter": "A",
        "text": "II ve III"
      },
      {
        "letter": "B",
        "text": "Yalnız I"
      },
      {
        "letter": "C",
        "text": "Yalnız II"
      },
      {
        "letter": "D",
        "text": "I ve III"
      },
      {
        "letter": "E",
        "text": "I, II ve III"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "L-selektin (CD62L), lökosit yüzeyinde eksprese edilen bir adezyon molekülüdür; dolaşımdaki **nötrofiller (II)** ve naif **T lenfositler (III)** yüzeyinde bulunur ve yüksek endotelli venüllere tutunmada görev alır. Endotelde ise E ve P-selektin bulunur.",
    "note": "",
