    "open_answer": "",
    "explanation": "Fizyolojik hemostazda koagülasyon kaskadını tetikleyen temel in vivo olay, vasküler hasar bölgesinde açığa çıkan subendotelyal **Doku Faktörü (TF / Tromboplastin)** salınımı ve bunun Faktör VIIa ile birleşerek ekstrensek yolağı başlatmasıdır.",
