    "question": "Hemodinamik prensiplere göre damar direncinin; damar uzunluğu ve kanın viskozitesi ile doğru; damar yarıçapının dördüncü kuvveti ile ters orantılı olduğu yasa ya da eşitlik hangisidir?",
