    "question": "Hipoksik pulmoner vazokonstrüksiyonun mekanizmasıyla ilgili verilen önermelerden hangisi/hangileri doğrudur? I- Endoplazmik retikulum redoks sinyali mekanizmayı başlatır    II- Kalsiyum III- Potasyum kanalları açılır          IV- Tirozin kinaz yolakları üzerinden etki oluşur",
