    "q_num": 66,
    "subject": "Fizyoloji",
    "professor": "Arzu Şahin",
    "question": "\"Hb’in O2 ile bağlanması CO2’nin uzaklaşmasına sebep olur ve böylece kandan CO2’nin alveole geçişini artırır.\" Bu olay aşağıdaki ifadelerden hangisini tanımlar?",
