    "question": "Derin su dalışlarından sonra yüzeye hızla çıkılmasıyla gelişen dekompresyon hastalığında (vurgun), doku ve vücut sıvılarında gaz kabarcıkları oluşturarak semptomların gelişmesine neden olan başlıca gaz aşağıdakilerden hangisidir?",
