    "answer": "B",
    "open_answer": "Azot,azot,N,azot gazı,azot konsantrasyon artışına bağlı olarak azotun gaz hale geçmesi, bu durum dalgıçların su yüzeyine ani olarak çıkması ile oluşabilir,azotun kanda çözünmesi,azot basıncının artması,azot zehirlenmesi",
    "explanation": "Dekompresyon hastalığında (vurgun), yüksek çevre basıncında dokularda çözünmüş olan **azot gazı (N₂)**, ani basınç düşüşünde gaz kabarcıklarına dönüşerek vasküler emboliye ve doku iskemisine yol açar.",
