    "open_answer": "",
    "explanation": "Restriktif akciğer hastalıklarında akciğer hacimleri (FVC, TLC) kısıtlanır ve kompliyans azalır; ancak **hava yollarında tıkanıklık (obstrüksiyon) bulunmaz** ve FEV1/FVC oranı normaldir. Dolayısıyla A seçeneği yanlıştır.",
