    "professor": "Belirtilmemiş",
    "question": "Oskültasyonda atriyal sistol sırasında sertleşmiş ventrikül duvarına kanın çarpmasıyla duyulan ve 'atriyal gallop' olarak da adlandırılan patolojik kalp sesi hangisidir?",
