    "professor": "Belirtilmemiş",
    "question": "Fizyolojideki klasik formüle (Maksimum Kalp Hızı = 220 - Yaş) göre, 60 yaşındaki sağlıklı bir bireyin teorik maksimum kalp atım hızı kaç atım/dakikadır?",
