    "explanation": "Teorik maksimum kalp hızı **HRmax = 220 - Yaş** formülü ile hesaplanır; 60 yaşındaki bir kişi için bu değer **220 - 60 = 160 atım/dakika (bpm)** olarak belirlenir.",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
