    "options": [
      {
        "letter": "A",
        "text": "Böbreklerden idrarla H+ sekresyonunu artırmak"
      },
      {
        "letter": "B",
        "text": "Hipoventilasyon yaparak karbondioksit tutulumunu artırmak"
      },
      {
        "letter": "C",
        "text": "Hiperventilasyon ile CO2 atılımını artırmak"
      },
      {
        "letter": "D",
        "text": "Böbreklerden yeni HCO3- sentezini ve geri emilimini artırmak"
      },
      {
        "letter": "E",
        "text": "Hücre dışı H+ iyonlarının hücre içi tamponlarla değişimi"
      }
    ],
    "answer": "B",
    "open_answer": "Hipoventilasyon",
    "explanation": "Asidoz durumunda solunum sistemi **hiperventilasyon** ile CO₂ atılımını artırarak pH'yı dengeler; **hipoventilasyon** ise CO₂ tutulumunu artırıp asidozu daha da derinleştireceğinden kompansatuar olamaz.",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
