    "answer": "D",
    "open_answer": "Alveoler yüzey gerilimi azalır; farklı çaplardaki alveollerin iç basınçları eşitlenir.",
    "explanation": "**Pulmoner sürfaktan**, yüzey gerilimini düşürür; Laplace yasası (P=2T/r) uyarınca küçük alveollerde daha yoğunlaşarak gerilimi daha fazla azaltır, iç basınçları eşitler ve atelektaziyi önler.",
