    "explanation": "Alveoler hipoksi pulmoner dolaşımda kanı iyi havalanan alanlara yönlendirmek için **pulmoner vazokonstriksiyon** yaparken; periferik doku hipoksisi perfüzyonu artırmak için **sistemik vazodilatasyon** oluşturur.",
